import { chromium } from '@playwright/test'
import { createServer } from 'node:http'
import { readFileSync, existsSync, statSync } from 'node:fs'
import { join, extname } from 'node:path'

const ROOT = 'dist-remote'
const PNG = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aD1sAAAAASUVORK5CYII=', 'base64')
const MIME = { '.html':'text/html', '.js':'application/javascript', '.css':'text/css', '.svg':'image/svg+xml', '.png':'image/png', '.json':'application/json', '.woff2':'font/woff2' }

const server = createServer((req, res) => {
  const url = req.url.split('?')[0]
  if (url.startsWith('/api/v2.0/code')) {
    // 返回真实形态的图形验证码：{ code:200, captchaOnOff:true, uuid, data:<base64 png> }
    res.writeHead(200, { 'Content-Type': 'application/json' })
    res.end(JSON.stringify({ code: 200, captchaOnOff: true, uuid: 'mock-uuid-123', data: PNG.toString('base64') }))
    return
  }
  let p = join(ROOT, url === '/' ? 'index.html' : url)
  if (!existsSync(p) || statSync(p).isDirectory()) p = join(ROOT, 'index.html')
  try {
    const buf = readFileSync(p)
    res.writeHead(200, { 'Content-Type': MIME[extname(p)] || 'application/octet-stream' })
    res.end(buf)
  } catch { res.writeHead(404); res.end('nf') }
})
await new Promise(r => server.listen(8199, r))
console.log('mock server on 8199')

const browser = await chromium.launch({ executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE })
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
await page.route(/font|woff2?|\.ttf|\.otf/i, r=>r.abort()).catch(()=>{})
await page.goto('http://127.0.0.1:8199/', { waitUntil: 'domcontentloaded' })
await page.waitForTimeout(2500)
const img = page.locator('.login-captcha-image')
const cnt = await img.count()
let src = ''
if (cnt) src = (await img.getAttribute('src')) || ''
console.log('captcha image element count:', cnt, 'src startsWith data:', src.startsWith('data:image'))
const phVisible = await page.locator('.login-captcha-ph').count()
console.log('placeholder text elements (should be 0 if image shown):', phVisible)
await page.screenshot({ path: 'artifacts/captcha-remote-proof.png', animations:'disabled', timeout:30000 }).catch(()=>{})
await browser.close()
server.close()

