test('登录页（主）：用户/机构 tab + 账号密码登录', async ({ page }) => {
  await page.goto('/', { waitUntil: 'domcontentloaded' })
  await page.waitForTimeout(1500)

  // 顶部标题 + 品牌名
  await expect(page.getByText('登录', { exact: true }).first()).toBeVisible()
  await expect(page.getByText('苏州市服务监管平台').first()).toBeVisible()

  // 用户登录 / 机构登录 分段切换
  const segs = page.locator('.login-seg-btn')
  await expect(segs).toHaveCount(2)
  await expect(segs.nth(0)).toHaveText('用户登录')
  await expect(segs.nth(1)).toHaveText('机构登录')
  await expect(segs.nth(0)).toHaveClass(/active/)

  // 用户登录字段：用户名/身份证号码/手机号码 + 登录密码 + 图形验证码
  const labels = page.locator('.login-field-label')
  await expect(labels.nth(0)).toContainText('用户名/身份证号码/手机号码')
  await expect(labels.nth(1)).toContainText('登录密码')
  await expect(labels.nth(2)).toContainText('图形验证码')
  await expect(page.getByText('验证码登录').first()).toBeVisible()
  await expect(page.locator('.login-captcha-img')).toBeVisible()
  await expect(page.getByText('请勾选同意用户协议和隐私协议').first()).toBeVisible()
  const submit = page.locator('.login-submit')
  await expect(submit).toContainText('登录')

  // 切到机构登录：统一社会信用代码
  await segs.nth(1).click()
  await page.waitForTimeout(300)
  await expect(page.locator('.login-field-label').nth(0)).toContainText('统一社会信用代码')
  await expect(page.locator('.login-seg-btn').nth(1)).toHaveClass(/active/)

  // 几何断言（参考站规范）
  const card = page.locator('.login-card')
  const cardBox = await card.boundingBox()
  expect(Math.round(cardBox!.x)).toBe(16)
  expect(Math.round(cardBox!.width)).toBe(358)
  const segBox = await page.locator('.login-segmented').boundingBox()
  expect(Math.round(segBox!.height)).toBe(52)
  expect(Math.round((await submit.boundingBox())!.height)).toBe(48)

